module TopModule (
  input [2:0] in,
  output [1:0] out
);
  // Declare a variable to hold the count of '1's
  reg [1:0] count;

  // Process the input vector
  always @(posedge in) begin
    // Initialize the count to 0
    count = 2'b00;

    // Iterate through each bit of the input vector
    for (int i = 0; i < 3; i++) begin
      // Increment the count if the current bit is '1'
      if (in[i] == 1'b1) begin
        count = count + 1'b1;
      end
    end
  end

  // Assign the count to the output
  assign out = count;
endmodule

