module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  // Declare the carry-in and carry-out signals
  wire cin1, cin2, cout1, cout2;

  // Declare the sum and carry-out signals
  wire sum1, sum2, sum3, sum4;

  // Declare the full adder logic
  full_adder fa1(a, b, cin, sum1, cout1);
  full_adder fa2(sum1, cin, sum2, cout2);
  full_adder fa3(sum2, cin, sum3, cout3);
  full_adder fa4(sum3, cin, sum4, cout4);

  // Connect the sum and carry-out signals
  assign sum = sum4;
  assign cout = cout4;

endmodule

