module TopModule (
  input clk,
  input [7:0] d,
  input reset,
  output reg [7:0] q
);

  // D flip-flops with active high synchronous reset
  reg [7:0] dffs [0:7];

  // Initialize D flip-flops to zero
  initial begin
    for (int i = 0; i < 8; i = i + 1) begin
      dffs[i] = 0;
    end
  end

  // Trigger D flip-flops on positive edge of clk
  always @(posedge clk) begin
    if (reset) begin
      for (int i = 0; i < 8; i = i + 1) begin
        dffs[i] = 0;
      end
    end else begin
      for (int i = 0; i < 8; i = i + 1) begin
        dffs[i] = d[i];
      end
    end
  end

  // Output the current state of the D flip-flops
  assign q = dffs;

endmodule

