module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);
  // Define the 7420 chip with two 4-input NAND gates
  wire nand1a, nand1b, nand1c, nand1d, nand2a, nand2b, nand2c, nand2d;
  wire nand1y, nand2y;

  // Connect the inputs to the NAND gates
  nand1a = !p1a & !p1b & !p1c & !p1d;
  nand1b = !p1a & !p1b & !p1c & p1d;
  nand1c = !p1a & !p1b & p1c & !p1d;
  nand1d = !p1a & !p1b & p1c & p1d;
  nand2a = !p2a & !p2b & !p2c & !p2d;
  nand2b = !p2a & !p2b & !p2c & p2d;
  nand2c = !p2a & !p2b & p2c & !p2d;
  nand2d = !p2a & !p2b & p2c & p2d;

  // Connect the outputs of the NAND gates to the outputs of the module
  assign p1y = nand1y;
  assign p2y = nand2y;
endmodule

module TopModule (
  input clk,
  input reset,
  input [31:0] in,
  output reg [31:0] out
);

reg [31:0] current_state;
reg [31:0] next_state;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    current_state <= 32'b0;
    next_state <= 32'b0;
  end else begin
    next_state <= in;
    if (current_state == next_state) begin
      out <= 32'b0;
    end else begin
      out <= 32'b1;
    end
    current_state <= next_state;
  end
end

endmodule

module TopModule (
  input clk,
  input slowena,
  input reset,
  output reg [3:0] q
);

  reg [3:0] count;
  reg [1:0] state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 4'b0000;
      state <= 2'b00;
    end else begin
      if (slowena) begin
        case (state)
          2'b00: begin
            if (count == 4'b0009) begin
              count <= 4'b0000;
              state <= 2'b01;
            end else begin
              count <= count + 1'b1;
            end
          end
          2'b01: begin
            if (count == 4'b0009) begin
              count <= 4'b0000;
              state <= 2'b00;
            end else begin
              count <= count + 1'b1;
            end
          end
          default: state <= 2'b00;
        endcase
      end else begin
        state <= 2'b00;
      end
    end
  end

  assign q = count;

endmodule

module TopModule (
