  reg [3:0] digit1, digit2, digit3, digit4;
  reg [3:0] digit1_ena, digit2_ena, digit3_ena, digit4_ena;
  reg [3:0] digit1_next, digit2_next, digit3_next, digit4_next;
  reg [3:0] digit1_ena_next, digit2_ena_next, digit3_ena_next, digit4_ena_next;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      digit1 <= 4'b0000;
      digit2 <= 4'b0000;
      digit3 <= 4'b0000;
      digit4 <= 4'b0000;
      digit1_ena <= 4'b0000;
      digit2_ena <= 4'b0000;
      digit3_ena <= 4'b0000;
      digit4_ena <= 4'b0000;
    end else begin
      digit1_next <= digit1 + 1'b1;
      digit2_next <= digit2 + 1'b1;
      digit3_next <= digit3 + 1'b1;
      digit4_next <= digit4 + 1'b1;

      digit1_ena_next <= digit1_next[3];
      digit2_ena_next <= digit2_next[2];
      digit3_ena_next <= digit3_next[1];
      digit4_ena_next <= digit4_next[0];

      digit1 <= digit1_next;
      digit2 <= digit2_next;
      digit3 <= digit3_next;
      digit4 <= digit4_next;

      digit1_ena <= digit1_ena_next;
      digit2_ena <= digit2_ena_next;
      digit3_ena <= digit3_ena_next;
      digit4_ena <= digit4_ena_next;
    end
  end

  assign ena = {digit1_ena, digit2_ena, digit3_ena, digit4_ena};
  assign q = {digit4, digit3, digit2, digit1};

endmodule

