always @(posedge clk or negedge clk) begin
  case (state)
    2'b00: begin
      if (d) state <= 2'b01;
      else state <= 2'b00;
    end
    2'b01: begin
      if (d) state <= 2'b10;
      else state <= 2'b01;
    end
    2'b10: begin
      if (d) state <= 2'b11;
      else state <= 2'b10;
    end
    2'b11: begin
      if (d) state <= 2'b00;
      else state <= 2'b11;
    end
  endcase
end

assign q = state[0];

endmodule

