  end
endmodule

module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  // 8-bit shift register with 8 D-type flip-flops
  reg [7:0] shiftRegister;

  // Multiplexers for the 3-input logic function
  reg [2:0] multiplexerSelect;
  reg [7:0] multiplexerOutput;

  // 3-input logic function
  always @(posedge clk or posedge enable) begin
    if (enable) begin
      // Determine the multiplexer select based on ABC
      multiplexerSelect = {A, B, C};

      // Select the appropriate output from the shift register
      multiplexerOutput = shiftRegister[multiplexerSelect];

      // Assign the output to Z
      Z <= multiplexerOutput;
    end else begin
      // Reset the shift register
      shiftRegister <= 8'b0;
      Z <= 1'b0;
    end
  end

  // Shift the shift register on the positive edge of the clock
  always @(posedge clk) begin
    if (enable) begin
      // Shift the shift register
      shiftRegister <= {shiftRegister[6:0], S};
    end
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input load,
  input ena,
  input [3:0] data,
  output reg [3:0] q
);

  reg [3:0] shift_reg;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      shift_reg <= 4'b0000;
    end else if (load) begin
      shift_reg <= data;
    end else if (ena) begin
      shift_reg <= {shift_reg[3], shift_reg[2:0]};
    end
  end

  assign q = shift_reg;

endmodule

