  reg [1:0] state;
  reg [1:0] next_state;

  // Define the flip-flops
  reg [1:0] y1_flipflop;
  reg [1:0] y3_flipflop;

  // Define the state assignment logic
  always @(posedge w) begin
    state <= next_state;
  end

  always @(posedge y) begin
    case (state)
      2'b00: begin
        next_state <= 2'b01;
        y1_flipflop <= 1'b1;
        y3_flipflop <= 1'b0;
      end
      2'b01: begin
        next_state <= 2'b10;
        y1_flipflop <= 1'b0;
        y3_flipflop <= 1'b1;
      end
      2'b10: begin
        next_state <= 2'b11;
        y1_flipflop <= 1'b1;
        y3_flipflop <= 1'b0;
      end
      2'b11: begin
        next_state <= 2'b00;
        y1_flipflop <= 1'b0;
        y3_flipflop <= 1'b1;
      end
    endcase
  end

  // Assign the outputs
  assign Y1 = y1_flipflop;
  assign Y3 = y3_flipflop;

endmodule

