);

  reg [63:0] shift_register;
  reg [1:0] shift_direction;
  reg [7:0] shift_amount;

  always @(posedge clk or posedge load) begin
    if (load) begin
      shift_register <= data;
      shift_direction <= 2'b00;
      shift_amount <= 8'b00000000;
    end else if (ena) begin
      case (amount)
        2'b00: begin
          shift_direction <= 2'b00;
          shift_amount <= 8'b00000000;
        end
        2'b01: begin
          shift_direction <= 2'b00;
          shift_amount <= 8'b11111111;
        end
        2'b10: begin
          shift_direction <= 2'b10;
          shift_amount <= 8'b00000000;
        end
        2'b11: begin
          shift_direction <= 2'b10;
          shift_amount <= 8'b11111111;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    case (shift_direction)
      2'b00: begin
        if (shift_amount == 8'b00000000) begin
          q <= shift_register;
        end else if (shift_amount == 8'b11111111) begin
          q <= {shift_register[63:0], shift_register[63:0]};
        end else begin
          q <= {shift_register[63:shift_amount], shift_register[shift_amount-1:0]};
        end
      end
      2'b10: begin
        if (shift_amount == 8'b00000000) begin
          q <= {shift_register[63:0], shift_register[63:0]};
        end else if (shift_amount == 8'b11111111) begin
          q <= {shift_register[63:0], shift_register[63:0]};
        end else begin
          q <= {shift_register[shift_amount-1:0], shift_register[63:shift_amount]};
        end
      end
    endcase
  end

