  input areset,
  input predict_valid,
  input predict_taken,
  output logic [31:0] predict_history,

  input train_mispredicted,
  input train_taken,
  input [31:0] train_history
);

  // Define the global history shift register
  reg [31:0] history;
  reg [31:0] history_backup;

  // Initialize the history register
  initial begin
    history = 0;
    history_backup = 0;
  end

  // Update the history register based on the prediction and misprediction
  always @(posedge clk or posedge areset) begin
    if (areset) begin
