  reg [1:0] next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= 2'b00;
      z <= 1'b0;
    end else begin
      next_state = state;
      case (state)
        2'b00: begin
          if (w) begin
            next_state <= 2'b01;
          end else begin
            next_state <= 2'b00;
          end
        end
        2'b01: begin
          if (w) begin
            next_state <= 2'b10;
          end else begin
            next_state <= 2'b01;
          end
        end
        2'b10: begin
          if (w) begin
            next_state <= 2'b11;
          end else begin
            next_state <= 2'b10;
          end
        end
        2'b11: begin
          if (w) begin
            next_state <= 2'b00;
          end else begin
            next_state <= 2'b11;
          end
        end
      endcase
      state <= next_state;
      z <= (state == 2'b00);
    end
  end

endmodule

