module TopModule (
  input clk,
  input in,
  input reset,
  output [7:0] out_byte,
  output done
);

  // Define the states of the FSM
  typedef enum {IDLE, START, DATA, STOP} state_t;
  state_t state = IDLE;

  // Define the variables for the FSM
  reg [7:0] byte;
  reg [1:0] bit_count;
  reg [1:0] stop_bit_count;
  reg [1:0] start_bit_count;

  // Define the logic for the FSM
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state = IDLE;
      byte = 8'b0;
      bit_count = 2'b0;
      stop_bit_count = 2'b0;
      start_bit_count = 2'b0;
    end else begin
      case (state)
        IDLE: begin
          if (in == 1'b0) begin
            state = START;
            start_bit_count = 2'b0;
          end
        end
        START: begin
          if (in == 1'b1) begin
            state = DATA;
            bit_count = 2'b0;
            start_bit_count = 2'b1;
          end
        end
        DATA: begin
          if (in == 1'b0) begin
            byte = byte << 1;
            bit_count = bit_count + 1;
            if (bit_count == 8) begin
              state = STOP;
              stop_bit_count = 2'b0;
            end
          end
        end
        STOP: begin
          if (in == 1'b1) begin
            byte = byte << 1;
            bit_count = bit_count + 1;
            if (bit_count == 8) begin
              state = IDLE;
              done = 1'b1;
            end
          end
          else begin
            state = STOP;
            stop_bit_count = stop_bit_count + 1;
            if (stop_bit_count == 2) begin
              state = IDLE;
              done = 1'b0;
            end
          end
        end
      endcase
    end
  end

  // Define the output logic
  assign out_byte = byte;
  assign done = done;

endmodule

module TopModule (
