module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);

    reg [7:0] counter;
    reg [1:0] tick_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 8'b0;
            tick_reg <= 2'b0;
        end else begin
            if (counter == div - 1) begin
                counter <= 8'b0;
                tick_reg <= ~tick_reg;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    assign tick = tick_reg;

endmodule

module addmulxor_1_stage_unsigned_9_bit_xor_reduction(
	input  [8:0] a,
	input  [8:0] b,
	input  [8:0] c,
	input  [8:0] d,
	output [8:0] out,
	input clk);

reg [17:0] stage0;
reg [8:0] result;

always @(posedge clk) begin
    // Compute the intermediate 18-bit result
    stage0 = (d + a) * b;

    // Perform XOR reduction on the 18-bit result
    result = stage0[17] ^ stage0[16] ^ stage0[15] ^ stage0[14] ^ stage0[13] ^ stage0[12] ^ stage0[11] ^ stage0[10] ^ stage0[9];

    // Output the result
    out <= result;
end

endmodule

module alu(
    input var [32:0]in_a,
    input var [32:0]in_b,
    input var [4:0]alu_op,

    output [31:0]rd_val_out,
    output lt,
    output ltu,
    output eq
    );

    // Internal wires for intermediate calculations
    wire [32:0] in_b_twos_complement;
    wire [32:0] result;
    wire [32:0] result_twos_complement;

    // Convert in_b to two's complement if it's a subtraction operation
    assign in_b_twos_complement = alu_op == 5'b00000 ? ~in_b + 1 : in_b;

    // Perform the selected ALU operation
    always_comb begin
        case (alu_op)
            5'b00000: result = in_a + in_b_twos_complement; // Addition
            5'b00001: result = in_a - in_b_twos_complement; // Subtraction
            5'b00010: result = in_a < in_b_twos_complement ? 1'b1 : 1'b0; // Signed less than
            5'b00011: result = in_a < in_b_twos_complement ? 1'b1 : 1'b0; // Signed less than unsigned
            5'b00100: result = in_a ^ in_b; // XOR
            5'b00101: result = in_a | in_b; // OR
            5'b00110: result = in_a & in_b; // AND
            5'b00111: result = in_a; // Load upper immediate (LUI)
            default: result = 32'b0; // Default operation
        endcase
    end

    // Convert the result back to two's complement if it's a subtraction operation
    assign result_twos_complement = alu_op == 5'b00000 ? ~result + 1 : result;

    // Compute the status flags
    assign lt = result_twos_complement[31];
    assign ltu = result_twos_complement[31] && result_twos_complement[30];
    assign eq = result_twos_complement == 0;

    // Assign the result to rd_val_out
    assign rd_val_out = result;

endmodule

module addmuladd_2_stage_signed_16_bit(
	input signed [15:0] a,
	input signed [15:0] b,
	input signed [15:0] c,
	input signed [15:0] d,
	output [15:0] out,
	input clk);

reg [15:0] stage0;
reg [15:0] stage1;

always @(posedge clk) begin
    stage0 <= (d + a) * b;
    stage1 <= stage0 + c;
    out <= stage1;
end

endmodule

module fsm_global
(
	input wire					clk,
	input wire 					rst_n,
	input wire					clk_cam,

	input wire		[9:0]		input_wrusedw,
	input wire		[11:0]		output_rdusedw,
	input wire					VSYNC_cam,
	input wire					HREF_cam,
	output wire					p_VSYNC_cam,

	input wire					wr_input_fifo,
	output wire					rd_input_fifo,

	output wire					wr_strobe,
	output wire					rd_strobe,
	output wire					write_strobe,
	output wire					read_strobe,
	output wire					wait_strobe,
	output wire					idle_strobe,

	input wire					sd_ready,
	input wire					valid_data,

	input wire					STOP_capt
);

// Internal registers and counters
reg [2:0] state;
reg [1:0] input_fifo_status;
reg [1:0] output_fifo_status;
reg [1:0] sd_ready_status;
reg [1:0] valid_data_status;
reg [1:0] stop_capt_status;

// Internal signals
reg [1:0] input_fifo_counter;
reg [1:0] output_fifo_counter;
reg [1:0] sd_ready_counter;
reg [1:0] valid_data_counter;
reg [1:0] stop_capt_counter;

// Internal logic
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		state <= 3'b000;
		input_fifo_status <= 2'b00;
		output_fifo_status <= 2'b00;
		sd_ready_status <= 2'b00;
		valid_data_status <= 2'b00;
		stop_capt_status <= 2'b00;
		input_fifo_counter <= 2'b00;
		output_fifo_counter <= 2'b00;
		sd_ready_counter <= 2'b00;
		valid_data_counter <= 2'b00;
		stop_capt_counter <= 2'b00;
