module UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);

reg [2:0] TxState = TxIdle;
reg [2:0] RxState = RxIdle;
reg [10:0] TxBdCount = 0;
reg [10:0] RxBdCount = 0;
reg [7:0] TxData = 0;
reg [7:0] RxData = 0;
reg [1:0] opTxBusy = 0;
reg [1:0] opRxValid = 0;

always @(posedge ipClk or posedge ipReset) begin
	if (ipReset) begin
		TxState <= TxIdle;
		RxState <= RxIdle;
		TxBdCount <= 0;
		RxBdCount <= 0;
		TxData <= 0;
		RxData <= 0;
		opTxBusy <= 0;
		opRxValid <= 0;
	end else begin
		case (TxState)
			TxIdle: begin
				if (ipTxSend) begin
					TxState <= Sending;
					TxData <= 0;
					TxBdCount <= 0;
				end
			end
			Sending: begin
				if (TxBdCount == 433) begin
					TxState <= TxDone;
					TxBdCount <= 0;
				end else begin
					TxBdCount <= TxBdCount + 1;
					opTx <= 1;
				end
			end
			TxDone: begin
				TxState <= TxIdle;
				opTxBusy <= 0;
			end
		endcase

		case (RxState)
			RxIdle: begin
				if (ipRx) begin
					RxState <= Receiving;
					RxData <= 0;
					RxBdCount <= 0;
				end
			end
			Receiving: begin
				if (RxBdCount == 433) begin
					RxState <= RxDone;
					RxBdCount <= 0;
					opRxData <= RxData;
					opRxValid <= 1;
				end else begin
					RxBdCount <= RxBdCount + 1;
					RxData <= RxData << 1;
					RxData = RxData | (ipRx ? 1 : 0);
				end
			end
			RxDone: begin
				RxState <= RxIdle;
				opRxValid <= 0;
			end
		endcase
	end
end

endmodule

