	output [9:0] out,
	input clk);

reg [19:0] stage0;
reg [19:0] stage1;

always @(posedge clk) begin
    stage0 <= (a * b) - c;
    stage1 <= stage0;
end

assign out = stage1;

endmodule

module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);

    // Internal state variables
    reg [9:0] key_index;
    reg [9:0] key_sequence;
    reg [9:0] key_count;

    // Clock and reset sensitive process
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            key_index <= 0;
            key_sequence <= 0;
            key_count <= 0;
        end else begin
            // Increment key index
            key_index <= key_index + 1;

            // Check if key index is within the sequence length
            if (key_index < 10) begin
                // Increment key count
                key_count <= key_count + 1;

                // Output the key
                keypress <= key_sequence[key_index];

                // Reset key count after 20 clock cycles
                if (key_count == 20) begin
                    key_count <= 0;
                end
            end else begin
                // Output the same key indefinitely
                keypress <= key_sequence[key_index - 10];
            end
        end
    end

    // Generate a sequence of keypress values
    always @(*) begin
        key_sequence = {10'b0000000000, 10'b0000000001, 10'b0000000010, 10'b0000000011, 10'b0000000100, 10'b0000000101, 10'b0000000110, 10'b0000000111, 10'b0000001000};
    end

endmodule

module submulxor_2_stage_signed_9_bit(
	input signed [8:0] a,
	input signed [8:0] b,
	input signed [8:0] c,
	input signed [8:0] d,
	output [8:0] out,
	input clk);

reg [17:0] stage0;
reg [17:0] stage1;

always @(posedge clk) begin
    // Stage 0: (d - a) * b
    stage0 = (d - a) * b;

    // Stage 1: (d - a) * b ^ c
    stage1 = stage0 ^ c;

    // Output: stage1
    out <= stage1;
end

endmodule

module submulsub_3_stage_unsigned_8_bit_xor_reduction(
	input  [7:0] a,
	input  [7:0] b,
	input  [7:0] c,
	input  [7:0] d,
	output [7:0] out,
	input clk);

reg [15:0] stage0, stage1, stage2;
reg [7:0] result;

always @(posedge clk) begin
    // Stage 1: a - b
    stage1 <= a - b;

    // Stage 2: stage1 * c
    stage2 <= stage1 * c;

    // Stage 3: stage2 - d
    result <= stage2 - d;

    // Output: XOR reduction of stage3
    out <= result[7];
end

endmodule

module submuland_1_stage_signed_13_bit(
	input signed [12:0] a,
	input signed [12:0] b,
	input signed [12:0] c,
	input signed [12:0] d,
	output [12:0] out,
	input clk);

reg [25:0] stage0; // Internal 26-bit register to handle overflow

always @(posedge clk) begin
    // Compute the intermediate result of the multiplication and bitwise AND operation
    stage0 = ((d - a) * b) & c;

    // Assign the final result to the 13-bit output out
    out <= stage0[12:0];
end

endmodule

