module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);

reg [WIDTH-1:0] dat0, dat1;
reg [2:0] state;
reg [1:0] t0_status, i0_status;
reg [1:0] t0_valid_next, i0_valid_next;
reg [1:0] t0_ready_next, i0_ready_next;

always @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		dat0 <= 8'b0;
		dat1 <= 8'b0;
		state <= S0;
		t0_status <= 2'b0;
		i0_status <= 2'b0;
		t0_valid_next <= 1'b0;
		i0_valid_next <= 1'b0;
		t0_ready_next <= 1'b0;
		i0_ready_next <= 1'b0;
	end else begin
		case (state)
			S0: begin
				if (t0_valid && t0_ready) begin
					dat0 <= t0_data;
					t0_status <= 2'b1;
					i0_status <= 2'b0;
					t0_valid_next <= 1'b0;
					i0_valid_next <= 1'b0;
					t0_ready_next <= 1'b0;
					i0_ready_next <= 1'b0;
				end else begin
					t0_valid_next <= t0_valid;
					i0_valid_next <= i0_valid;
					t0_ready_next <= t0_ready;
					i0_ready_next <= i0_ready;
				end
			end
			S1: begin
				if (i0_valid && i0_ready) begin
					dat1 <= i0_data;
					t0_status <= 2'b0;
					i0_status <= 2'b1;
					t0_valid_next <= 1'b0;
					i0_valid_next <= 1'b0;
					t0_ready_next <= 1'b0;
					i0_ready_next <= 1'b0;
				end else begin
					t0_valid_next <= t0_valid;
					i0_valid_next <= i0_valid;
					t0_ready_next <= t0_ready;
					i0_ready_next <= i0_ready;
				end
			end
			S2: begin
				if (t0_valid && t0_ready) begin
					dat0 <= t0_data;
					t0_status <= 2'b1;
					i0_status <= 2'b0;
					t0_valid_next <= 1'b0;
					i0_valid_next <= 1'b0;
					t0_ready_next <= 1'b0;
					i0_ready_next <= 1'b0;
				end else begin
					t0_valid_next <= t0_valid;
					i0_valid_next <= i0_valid;
					t0_ready_next <= t0_ready;
					i0_ready_next <= i0_ready;
				end
			end
			S3: begin
				if (i0_valid && i0_ready) begin
					dat1 <= i0_data;
					t0_status <= 2'b0;
					i0_status <= 2'b1;
					t0_valid_next <= 1'b0;
					i0_valid_next <= 1'b0;
					t0_ready_next <= 1'b0;
					i0_ready_next <= 1'b0;
				end else begin
					t0_valid_next <= t0_valid;
					i0_valid_next <= i0_valid;
					t0_ready_next <= t0_ready;
					i0_ready_next <= i0_ready;
				end
			end
			S4: begin
				if (t0_valid && t0_ready) begin
					dat0 <= t0_data;
					t0_status <= 2'b1;
					i0_status <= 2'b0;
					t0_valid_next <= 1'b0;
					i0_valid_next <= 1'b0;
					t0_ready_next <= 1'b0;
					i0_ready_next <= 1'b0;
				end else begin
					t0_valid_next <= t0_valid;
					i0_valid_next <= i0_valid;
					t0_ready_next <= t0_ready;
					i0_ready_next <= i0_ready;
				end
			end
			default: begin
				t0_valid_next <= t0_valid;
				i0_valid_next <= i0_valid;
				t0_ready_next <= t0_ready;
				i0_ready_next <= i0_ready;
			end
		endcase
		state <= state + 1'b1;
		if (state == S4) begin
			state <= S0;
		end
	end
end

assign t0_data = dat0;
assign t0_valid = t0_valid_next;
assign t0_ready = t0_ready_next;

assign i0_data = dat1;
assign i0_valid = i0_valid_next;
assign i0_ready = i0_ready_next;

endmodule

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);

    // Internal memory array
    reg [WIDTH-1:0] mem[0:DEPTH-1];

    // Write and read pointers
    reg [WIDTH-1:0] wr_ptr, rd_ptr;
    reg [WIDTH-1:0] word_count;

    // Status signals
    reg prog_full_reg, full_reg, empty_reg;

    // Edge-triggered update signals
    reg wr_edge, rd_edge;

    // Reset signal
    always @(posedge clk or posedge reset_p) begin
        if (reset_p) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            word_count <= 0;
            prog_full_reg <= 0;
            full_reg <= 0;
            empty_reg <= 1;
            overflow <= 0;
            underflow <= 0;
        end else begin
            if (wr_edge) begin
                if (word_count < DEPTH) begin
                    mem[wr_ptr] <= data_i;
                    wr_ptr <= wr_ptr + 1;
                    word_count <= word_count + 1;
                    prog_full_reg <= 0;
                    full_reg <= 0;
                    empty_reg <= 0;
                    overflow <= 0;
                    underflow <= 0;
                end else begin
                    overflow <= 1;
                    prog_full_reg <= 1;
                    full_reg <= 1;
                    empty_reg <= 0;
                    overflow <= 1;
                    underflow <= 0;
                end
            end
            if (rd_edge) begin
                if (word_count > 0) begin
                    data_o <= mem[rd_ptr];
                    rd_ptr <= rd_ptr + 1;
                    word_count <= word_count - 1;
                    prog_full_reg <= 0;
                    full_reg <= 0;
                    empty_reg <= 1;
                    overflow <= 0;
                    underflow <= 0;
                end else begin
                    underflow <= 1;
                    prog_full_reg <= 1;
                    full_reg <= 1;
                    empty_reg <= 0;
                    overflow <= 0;
                    underflow <= 1;
                end
            end
        end
    end

    // Edge-triggered update signals
    always @(posedge clk) begin
        wr_edge <= (data_we && wr_ptr < DEPTH);
        rd_edge <= (data_rd && rd_ptr < DEPTH);
    end

    // Status signals
    assign prog_full = prog_full_reg;
    assign full = full_reg;
    assign empty = empty_reg;

endmodule

