module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
);

parameter total_pixels = 1920,
         sync_pulses = 2,
         blanking_intervals = 2;

reg [9:0] h_counter = 0;
reg [9:0] v_counter = 0;
reg [9:0] pixel_x = 0;
reg [9:0] pixel_y = 0;
reg visible_region = 0;

always @(posedge pixel_clk) begin
    if (h_counter == total_pixels - 1) begin
        h_counter <= 0;
        v_counter <= v_counter + 1;
    end else begin
        h_counter <= h_counter + 1;
    end

    if (v_counter == sync_pulses - 1) begin
        vsync <= 1;
    end else if (v_counter == total_pixels - sync_pulses) begin
        vsync <= 0;
    end else begin
        vsync <= 0;
    end

    if (h_counter == 0) begin
        pixel_x <= 0;
    end else begin
        pixel_x <= pixel_x + 1;
    end

    if (v_counter == 0) begin
        pixel_y <= 0;
    end else begin
        pixel_y <= pixel_y + 1;
    end

    if (h_counter == total_pixels - 1) begin
        visible_region <= 0;
    end else if (v_counter == sync_pulses - 1) begin
        visible_region <= 1;
    end else if (v_counter == total_pixels - sync_pulses - 1) begin
        visible_region <= 0;
    end else begin
        visible_region <= 1;
    end
end

endmodule

