module tone(
    input CLK,
    input[31:0] period, 
    output reg tone_out
    );

    // Define the prescaler and main counter
    reg [31:0] prescaler;
    reg [31:0] main_counter;
    reg [1:0] state;

    // Initialize the prescaler and main counter
    initial begin
        prescaler = 32'b0;
        main_counter = 0;
        state = 2'b00; // Initial state: reset
    end

    // Clock edge trigger for state transitions
    always @(posedge CLK) begin
        if (state == 2'b00) begin // Reset state
            prescaler = 32'b0;
            main_counter = 0;
            state = 2'b01; // Transition to count state
        end else if (state == 2'b01) begin // Count state
            prescaler = prescaler + 1;
            if (prescaler == period) begin
                state = 2'b10; // Transition to toggle state
                tone_out = ~tone_out; // Toggle tone output
            end
        end else if (state == 2'b10) begin // Toggle state
            state = 2'b00; // Reset state
        end
    end

endmodule

