output wire [1:0] count_o
) begin
    reg [1:0] counter;
    reg [1:0] count_out;

    always @(posedge clk_i) begin
        if (counter == 3'b11) begin
            counter <= 3'b00;
            count_out <= 2'b01;
        end else begin
