module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // State machine states
    typedef enum {ZERO, ONE, TWO} state_t;
    state_t state = ZERO;

    // Data registers
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;

    // State machine logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= 8'b0;
            data_p2 <= 8'b0;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && s_ready) begin
                        data_p1 <= s_data;
                        state <= ONE;
                    end
                end
                ONE: begin
                    if (s_valid && s_ready) begin
                        data_p2 <= s_data;
                        state <= TWO;
                    end
                end
                TWO: begin
                    if (m_ready) begin
                        m_data <= data_p2;
                        m_valid <= 1'b1;
                        state <= ZERO;
                    end
                end
                default: begin
                    state <= ZERO;
                end
            endcase
        end
    end

    // Output logic
    assign s_ready = state == ZERO;
    assign m_valid = state == TWO;

endmodule

