module submulxor_0_stage_signed_12_bit(
	input signed [11:0] a,
	input signed [11:0] b,
	input signed [11:0] c,
	input signed [11:0] d,
	output [11:0] out
	);

	// Subtract a from d
	signed [11:0] sub_result = d - a;

	// Multiply the result by b
	signed [22:0] mul_result = sub_result * b;

	// Perform a bitwise XOR operation with c
	signed [11:0] xor_result = mul_result ^ c;

	// Assign the final result to out
	out <= xor_result;

endmodule

module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
  reg [35:0] data0, data1;
  reg [35:0] src0_rdy, src1_rdy;
  reg [35:0] dst0_rdy, dst1_rdy;
  reg [35:0] eof;
  reg [35:0] match_data_reg;
  reg [35:0] match_mask_reg;
  reg [35:0] state;
  reg [35:0] next_state;

  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      data0 <= 0;
      data1 <= 0;
      src0_rdy <= 0;
      src1_rdy <= 0;
      dst0_rdy <= 0;
      dst1_rdy <= 0;
      eof <= 0;
      match_data_reg <= 0;
      match_mask_reg <= 0;
      state <= IDLE;
      next_state <= IDLE;
    end else if (clear) begin
      data0 <= 0;
      data1 <= 0;
      src0_rdy <= 0;
      src1_rdy <= 0;
      dst0_rdy <= 0;
      dst1_rdy <= 0;
      eof <= 0;
      match_data_reg <= 0;
      match_mask_reg <= 0;
      state <= IDLE;
      next_state <= IDLE;
    end else begin
      next_state <= state;
      if (state == IDLE) begin
        if (src_rdy_i) begin
          data0 <= data_i;
          src0_rdy <= 1;
          dst0_rdy <= 0;
          state <= DATA0;
        end else if (dst_rdy_i) begin
          data1 <= data_i;
          src1_rdy <= 0;
          dst1_rdy <= 1;
          state <= DATA1;
        end
      end else if (state == DATA0) begin
        if (data_i[35:0] == match_data_reg && data_i[35:0] == match_mask_reg) begin
          data0 <= data_i;
          src0_rdy <= 1;
          dst0_rdy <= 1;
          state <= IDLE;
        end else if (src_rdy_i) begin
          data0 <= data_i;
          src0_rdy <= 1;
          dst0_rdy <= 0;
          state <= DATA0;
        end else if (dst_rdy_i) begin
          data1 <= data_i;
          src1_rdy <= 0;
          dst1_rdy <= 1;
          state <= DATA1;
        end
      end else if (state == DATA1) begin
        if (data_i[35:0] == match_data_reg && data_i[35:0] == match_mask_reg) begin
          data1 <= data_i;
          src1_rdy <= 1;
          dst1_rdy <= 1;
          state <= IDLE;
        end else if (src_rdy_i) begin
          data0 <= data_i;
          src0_rdy <= 1;
          dst0_rdy <= 0;
          state <= DATA0;
        end else if (dst_rdy_i) begin
          data1 <= data_i;
          src1_rdy <= 0;
          dst1_rdy <= 1;
          state <= DATA1;
        end
      end
    end
  end

  always @(posedge clk) begin
    if (state == DATA0) begin
      data0_o <= data0;
      src0_rdy_o <= src0_rdy;
      dst0_rdy_o <= dst0_rdy;
    end else if (state == DATA1) begin
      data1_o <= data1;
      src1_rdy_o <= src1_rdy;
      dst1_rdy_o <= dst1_rdy;
    end
  end

  always @(posedge clk) begin
    if (state == DATA0) begin
      eof <= 0;
    end else if (state == DATA1) begin
      eof <= 0;
    end
  end

  always @(posedge clk) begin
    if (state == DATA0) begin
      match_data_reg <= match_data;
    end else if (state == DATA1) begin
      match_mask_reg <= match_mask;
    end
  end

  always @(posedge clk) begin
    if (state == DATA0) begin
      if (src_rdy_i) begin
        src0_rdy <= 1;
      end else if (dst_rdy_i) begin
        src0_rdy <= 0;
      end
    end else if (state == DATA1) begin
      if (src_rdy_i) begin
        src1_rdy <= 1;
      end else if (dst_rdy_i) begin
        src1_rdy <= 0;
      end
    end
  end
endmodule

