module divider 
#(
    parameter WIDTH=23,
    parameter MODULO=6000000
)
(
    input input_clk,
    output output_clk
);
    reg [WIDTH-1:0] counter;
    reg output_enable;
    reg [WIDTH-1:0] output_clk_reg;

    always @(posedge input_clk) begin
        if (counter == MODULO-1) begin
            output_enable <= ~output_enable;
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
