always @(posedge clk_6 or posedge reset) begin
    if (reset) begin
        prescaler <= 4'b0000;
        data_register <= 32'b00000000000000000000000000000000;
        output <= 32'b00000000000000000000000000000000;
    end else begin
        if (prescaler == 5'b1111) begin
            data_register <= data_register + 1'b1;
            prescaler <= 4'b0000;
        end else begin
            prescaler <= prescaler + 1'b1;
        end
        output <= data_register;
    end
end

