module dec2b2d(input rst, input [9:0]dig, output reg [3:0] uni, dec);
    // Reset the outputs to zero
    always @(posedge rst or negedge clk) begin
        uni <= 4'b0000;
        dec <= 4'b0000;
    end

    // Decode the 10-bit input into units and deciles
    always @(posedge clk or negedge rst) begin
        if (rst) begin
            uni <= 4'b0000;
            dec <= 4'b0000;
        end else begin
            // Find the position of the highest set bit
            reg [3:0] highest_bit_pos = 4'b0000;
            for (reg i = 0; i < 10; i = i + 1) begin
                if (dig[i] == 1) begin
                    highest_bit_pos = i;
                    break;
                end
            end

            // Assign the unit value based on the highest set bit position
            case (highest_bit_pos)
                0: uni <= 4'b0000;
                1: uni <= 4'b0001;
                2: uni <= 4'b0010;
                3: uni <= 4'b0011;
                4: uni <= 4'b0100;
                5: uni <= 4'b0101;
                6: uni <= 4'b0110;
                7: uni <= 4'b0111;
                8: uni <= 4'b1000;
                9: uni <= 4'b1001;
                default: uni <= 4'b0000;
            endcase

            // The decile output remains at zero in this design
            dec <= 4'b0000;
        end
    end
endmodule

