module CCarryLookaheadBlock_5_5_5_InOutT(pA4,pA3,pA2,pA1,pA0, pB4,pB3,pB2,pB1,pB0, r4,r3,r2,r1,r0, cIn, cOut);

input pA4,pA3,pA2,pA1,pA0, pB4,pB3,pB2,pB1,pB0, cIn;
output r4,r3,r2,r1,r0, cOut;

wire [4:0] pA = {pA4,pA3,pA2,pA1,pA0};
wire [4:0] pB = {pB4,pB3,pB2,pB1,pB0};
wire [4:0] sum = {r4,r3,r2,r1,r0};
wire [4:0] carry = {cIn,0,0,0,0};

// Calculate individual bit sums and carries
wire [4:0] s0 = pA[0] ^ pB[0] ^ carry[0];
wire [4:0] s1 = pA[1] ^ pB[1] ^ carry[1];
wire [4:0] s2 = pA[2] ^ pB[2] ^ carry[2];
wire [4:0] s3 = pA[3] ^ pB[3] ^ carry[3];
wire [4:0] s4 = pA[4] ^ pB[4] ^ carry[4];

wire [4:0] c0 = s0 & s1;
wire [4:0] c1 = s1 & s2;
wire [4:0] c2 = s2 & s3;
wire [4:0] c3 = s3 & s4;
wire [4:0] c4 = s4 & carry[4];

// Calculate lookahead carries
wire [4:0] l0 = s0 & c1;
wire [4:0] l1 = s1 & c2;
wire [4:0] l2 = s2 & c3;
wire [4:0] l3 = s3 & c4;
wire [4:0] l4 = s4 & carry[4];

// Combine intermediate results to get the final sum and carry
assign r4 = sum[4] ^ l0;
assign r3 = sum[3] ^ l1 ^ l0;
assign r2 = sum[2] ^ l2 ^ l1 ^ l0;
assign r1 = sum[1] ^ l3 ^ l2 ^ l1 ^ l0;
assign r0 = sum[0] ^ l4 ^ l3 ^ l2 ^ l1 ^ l0;

assign cOut = carry[4] ^ l4 ^ l3 ^ l2 ^ l1 ^ l0;

endmodule

