module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
) (
    // Internal registers
    reg [AW-1:0] addr_req;
    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [AW-1:0] subaddr;
    reg [AW-1:0] good;

    // Cache storage
    reg [AW-1:0] cache[0:1];

    // Data validity states
    reg [1:0] hit0;
    reg [1:0] hit1;

    // Combinational logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            addr_req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
            hit0 <= 0;
            hit1 <= 0;
        end else begin
            if (clr) begin
                addr_req <= 0;
                cached_addr0 <= 0;
                cached_addr1 <= 0;
                cached_data0 <= 0;
                cached_data1 <= 0;
                subaddr <= 0;
                good <= 0;
                hit0 <= 0;
                hit1 <= 0;
            end else begin
                if (addr_ok) begin
                    addr_req <= addr;
                end

                if (we) begin
                    if (addr_req == cached_addr0) begin
                        cached_data0 <= din;
                        hit0 <= 1;
                    end else if (addr_req == cached_addr1) begin
                        cached_data1 <= din;
                        hit1 <= 1;
                    end else begin
                        cache[0] <= addr_req;
                        cache[1] <= addr_req;
                        cached_data0 <= din;
                        cached_data1 <= din;
                        hit0 <= 0;
                        hit1 <= 0;
                    end
                end

                if (addr_req == cached_addr0) begin
                    subaddr <= addr_req;
                    good <= 1;
                end else if (addr_req == cached_addr1) begin
                    subaddr <= addr_req;
                    good <= 1;
                end else begin
                    subaddr <= addr_req;
                    good <= 0;
                end
            end
        end
    end

    // Sequential logic
    always @(posedge clk) begin
        if (hit0 == 1) begin
            sdram_addr <= addr_req;
            dout <= cached_data0;
            data_ok <= 1;
        end else if (hit1 == 1) begin
            sdram_addr <= addr_req;
            dout <= cached_data1;
            data_ok <= 1;
        end else begin
            sdram_addr <= addr_req;
            dout <= din;
            data_ok <= 1;
        end
    end

    // Memory request generation
    always @(posedge clk) begin
        if (addr_ok && we) begin
            if (addr_req == cached_addr0) begin
                req <= 1;
            end else if (addr_req == cached_addr1) begin
                req <= 1;
            end else begin
                req <= 0;
            end
        end else begin
            req <= 0;
        end
    end
endmodule

