module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
) begin
    // Internal registers to track current and next states
    reg [2:0] current_data;
    reg [2:0] next_data;
    reg [2:0] current_control;
    reg [2:0] next_control;

    // Sequential logic to update registers on clock edges
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_data <= 3'b000;
            current_control <= 3'b000;
        end else begin
            current_data <= next_data;
            current_control <= next_control;
        end
    end

    // Combinational logic to determine next states based on input conditions
    always @(posedge CLK) begin
        if (WR) begin
            next_data <= D;
            next_control <= A;
        end else if (RD) begin
            next_data <= current_data;
            next_control <= current_control;
        end else begin
            next_data <= current_data;
            next_control <= current_control;
        end
    end

    // Convert the stored data into a one-hot encoded output
    always @(posedge CLK) begin
        if (WR) begin
            Y <= {1'b0, current_data};
        end else if (RD) begin
            Y <= {1'b0, current_data};
        end else begin
            Y <= {1'b0, current_data};
        end
    end

    // Output the write control signal
    assign WCTRL = WR;
endmodule

