module parallel_if(
    input wire clk,
    input wire rst,
    input wire en,
    input wire up_en,
    input wire down_en,
    output reg [3:0] count
);

reg [3:0] temp_count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        temp_count <= 4'b0000;
    end else if (en) begin
        if (up_en) begin
            temp_count <= temp_count + 1'b1;
        end else if (down_en) begin
            temp_count <= temp_count - 1'b1;
        end
    end
end

assign count = temp_count;

endmodule

module address_comp(
