module tx_add_preamble(
input wire clk,
input wire data_valid_in,
input wire [7:0] data_in,
output reg data_valid_out,
output reg [7:0] data_out
) begin
    reg [63:0] delay_data;
    reg [7:0] delay_data_valid;
    reg [7:0] preamble_byte = 8'b11010101;
    reg [7:0] next_data;
    reg [7:0] next_preamble;
    reg [7:0] next_data_valid;
    reg [7:0] next_preamble_valid;
    reg [7:0] next_data_out;
    reg [7:0] next_preamble_out;

    always @(posedge clk) begin
        if (data_valid_in) begin
            next_data = data_in;
            next_data_valid = 1'b1;
        end else begin
            next_data = delay_data[63:0];
            next_data_valid = delay_data_valid[7:0];
        end

        if (delay_data_valid[7:0] == 8'b11111111) begin
            next_preamble = preamble_byte;
            next_preamble_valid = 1'b1;
        end else begin
            next_preamble = delay_data[63:0][7:0];
            next_preamble_valid = delay_data_valid[63:0][7:0];
        end

        if (next_data_valid && next_preamble_valid) begin
            next_data_out = next_data;
            next_preamble_out = next_preamble;
            delay_data_valid = delay_data_valid[63:0][7:0] << 1;
            delay_data = delay_data[63:0][63:1] << 1 | next_data;
        end else begin
            next_data_out = 8'b00000000;
            next_preamble_out = 8'b00000000;
            delay_data_valid = delay_data_valid[63:0][7:0] << 1;
            delay_data = delay_data[63:0][63:1] << 1 | 8'b00000000;
        end
    end

    assign data_valid_out = next_data_valid;
    assign data_out = next_data_out;
endmodule

