module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // State machine states
    typedef enum {ZERO, ONE, TWO} state_t;
    state_t state = ZERO;

    // Data pipeline stages
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;

    // Control signals
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;

    // Handshake signals
    reg s_ready;
    reg m_valid;

    // State machine logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= 0;
            data_p2 <= 0;
            load_p1 <= 0;
            load_p2 <= 0;
            load_p1_from_p2 <= 0;
            s_ready <= 0;
            m_valid <= 0;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && m_ready) begin
                        state <= ONE;
                        data_p1 <= s_data;
                        load_p1 <= 1;
                        load_p2 <= 0;
                        load_p1_from_p2 <= 0;
                        s_ready <= 0;
                        m_valid <= 0;
                    end
                end
                ONE: begin
                    if (s_valid && m_ready) begin
                        state <= TWO;
                        data_p2 <= s_data;
                        load_p1 <= 0;
                        load_p2 <= 1;
                        load_p1_from_p2 <= 0;
                        s_ready <= 0;
                        m_valid <= 0;
                    end
                end
                TWO: begin
                    if (s_valid && m_ready) begin
                        state <= ZERO;
                        data_p1 <= data_p2;
                        load_p1 <= 0;
                        load_p2 <= 0;
                        load_p1_from_p2 <= 1;
                        s_ready <= 0;
                        m_valid <= 0;
                    end
                end
                default: begin
                    state <= ZERO;
                    data_p1 <= 0;
                    data_p2 <= 0;
                    load_p1 <= 0;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 0;
                    s_ready <= 0;
                    m_valid <= 0;
                end
            endcase
        end
    end

    // Data transfer logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            m_data <= 0;
            m_valid <= 0;
        end else begin
            if (load_p1) begin
                m_data <= data_p1;
                m_valid <= 1;
            end else if (load_p2) begin
                m_data <= data_p2;
                m_valid <= 1;
            end else if (load_p1_from_p2) begin
                m_data <= data_p2;
                m_valid <= 1;
            end else begin
                m_data <= 0;
                m_valid <= 0;
            end
        end
    end

    // Handshake logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            s_ready <= 0;
            m_valid <= 0;
        end else begin
            if (state == ONE) begin
                s_ready <= 1;
            end else if (state == TWO) begin
                s_ready <= 1;
            end else if (state == ZERO) begin
                s_ready <= 0;
            end
            if (state == ONE || state == TWO) begin
                m_valid <= 1;
            end else if (state == ZERO) begin
                m_valid <= 0;
            end
        end
    end

endmodule

