module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
)
    (
        .clk(clk),
        .aclr(aclr),
        .empty_n(empty_n),
        .full_n(full_n),
        .read(read),
        .write(write),
        .dout(dout),
        .din(din)
    );

    // Define the FIFO depth and width
    localparam DEPTH = 1 << DEPTH_BITS;
    localparam WIDTH = DATA_BITS;

    // Define the memory array and index register
    reg [WIDTH-1:0] mem[0:DEPTH-1];
    reg [DEPTH_BITS-1:0] write_ptr;
    reg [DEPTH_BITS-1:0] read_ptr;
    reg [DEPTH_BITS-1:0] full;
    reg [DEPTH_BITS-1:0] empty;

    // Initialize the FIFO
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            write_ptr <= 0;
            read_ptr <= 0;
            full <= 0;
            empty <= 1;
        end else begin
            if (write && !full) begin
                mem[write_ptr] <= din;
                write_ptr <= write_ptr + 1;
                if (write_ptr == DEPTH) begin
                    write_ptr <= 0;
                end
                full <= 1;
            end
            if (read && !empty) begin
                dout <= mem[read_ptr];
                read_ptr <= read_ptr + 1;
                if (read_ptr == DEPTH) begin
                    read_ptr <= 0;
                end
                empty <= 1;
            end
        end
    end

    // Update the full and empty flags
    always @(posedge clk) begin
        if (write && !full) begin
            full <= 1;
        end else begin
            full <= 0;
        end
        if (read && !empty) begin
            empty <= 1;
        end else begin
            empty <= 0;
        end
    end

endmodule

