module FixedRoundSigned(
	clk,
	fixed_num,
	round,
	overflow
	);

	input clk;
	input signed [num_width - 1 : 0] fixed_num;
	output reg signed [res_width : 0] round;
	output reg overflow;

	reg [num_width - 1 : 0] original_num;
	reg [num_width - 1 : 0] extracted_bits;
	reg [num_width - 1 : 0] adjusted_bits;
	reg [res_width - 1 : 0] computed_round;
	reg [res_width - 1 : 0] final_round;
	reg [res_width - 1 : 0] overflow_flag;

	parameter num_width = 16;
	parameter res_width = 16;
	parameter fixed_point_position = 8;

	always @(posedge clk) begin
		original_num <= fixed_num;

		// Extract relevant bits for rounding
		extracted_bits <= original_num >> fixed_point_position;

		// Adjust bits based on sign and rounding flags
		case (original_num[fixed_point_position])
			1'b0: begin
				adjusted_bits <= extracted_bits;
			end
			1'b1: begin
				adjusted_bits <= ~extracted_bits;
			end
		endcase

		// Compute the final rounded value
		computed_round <= adjusted_bits + (original_num[fixed_point_position] ? 1 : 0);

		// Check for overflow
		overflow_flag <= (computed_round >> res_width) != (original_num >> res_width);

		// Update the final rounded value
		final_round <= computed_round;

		// Update the overflow flag
		overflow <= overflow_flag;
	end

endmodule

