module mult_a_signed_b_signed
#(
	parameter	A_WIDTH		= 3,
	parameter	B_WIDTH		= 3,
	parameter	Q_WIDTH		= A_WIDTH+B_WIDTH,
	parameter	LATENCY		= 1
)
(
	input	arst,
	input	clk,

	input signed	[A_WIDTH-1:0]	a,
	input signed	[B_WIDTH-1:0]	b,
	output signed	[Q_WIDTH-1:0]	o
);

reg [A_WIDTH-1:0] r_a_1P;
reg [B_WIDTH-1:0] r_b_1P;
reg [Q_WIDTH-1:0] r_q_P[LATENCY-1:0];

always @(posedge clk or posedge arst) begin
	if (arst) begin
		r_a_1P <= 0;
		r_b_1P <= 0;
		for (int i = 0; i < LATENCY; i++) begin
			r_q_P[i] <= 0;
		end
	end else begin
		r_a_1P <= a;
		r_b_1P <= b;
		for (int i = 0; i < LATENCY-1; i++) begin
			r_q_P[i] <= r_q_P[i+1];
		end
		r_q_P[LATENCY-1] <= r_a_1P * r_b_1P;
	end
end

assign o = r_q_P[LATENCY-1];

endmodule

