module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
) (
  // Internal registers to store intermediate results
  reg [NBITS-1:0] reg1 [0 :3],
  reg [NBITS-1:0] reg2 [0 :3],
  reg [NBITS-1:0] reg3 [0 :3],
  reg [NBITS-1:0] reg4 [0 :3],

  // Internal registers to store the final output
  reg [NBITS-1:0] final_output [0 :3],

  // Internal signal to control the multiplexer
  reg [1:0] mux_select
);

  // Process to divide the input data into four groups
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      for (int i = 0; i < 4; i++) begin
        reg1[i] <= 0;
        reg2[i] <= 0;
        reg3[i] <= 0;
        reg4[i] <= 0;
        final_output[i] <= 0;
      end
    end else begin
      for (int i = 0; i < 4; i++) begin
        reg1[i] <= rdata[i*256];
        reg2[i] <= rdata[i*256 + 256];
        reg3[i] <= rdata[i*256 + 512];
        reg4[i] <= rdata[i*256 + 768];
      end
    end
  end

  // Process to combine the intermediate results using logical OR operations
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      for (int i = 0; i < 4; i++) begin
        final_output[i] <= 0;
      end
    end else begin
      for (int i = 0; i < 4; i++) begin
        final_output[i] <= reg1[i] | reg2[i] | reg3[i] | reg4[i];
      end
    end
  end

  // Process to control the multiplexer
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      mux_select <= 0;
    end else begin
      if (valid_rd) begin
        mux_select <= 0;
      end else begin
        mux_select <= 1;
      end
    end
  end

  // Process to output the final result
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      hrdata <= 0;
    end else begin
      hrdata <= final_output[mux_select];
    end
  end

endmodule

module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // Internal registers
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg [1:0] state;

    // FSM states
    parameter ZERO = 2'b00;
    parameter ONE = 2'b01;
    parameter TWO = 2'b10;

    // FSM logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_p1 <= 0;
            data_p2 <= 0;
            state <= ZERO;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid) begin
                        data_p1 <= s_data;
                        state <= ONE;
                    end
                end
                ONE: begin
                    if (m_ready) begin
                        m_data <= data_p1;
                        m_valid <= 1;
                        state <= TWO;
                    end
                end
                TWO: begin
                    if (s_valid) begin
                        data_p2 <= s_data;
                        state <= ONE;
                    end
                end
            endcase
        end
    end

    // Output signals
    assign s_ready = state == ONE;
    assign m_ready = state == TWO;

endmodule

