                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );

    wire [63 : 0] a0, a1, b0, b1, b2, b3, c0, c1, d0, d1, d2, d3;

    always @* begin
        // Initialize internal registers
        a0 = a;
        a1 = b;
        b0 = c;
        b1 = d;
        b2 = m0;
        b3 = m1;
        c0 = a0;
        c1 = a1;
        d0 = b0;
