                y5 = u6 >> 1;
            end
            8'b00001000: begin
                y0 = u0 + s0;
                y1 = u2 + s1;
                y3 = u4 + s3;
                y5 = u6 + s5;
            end
            8'b00001001: begin
                y0 = u0 - s0;
                y1 = u2 - s1;
                y3 = u4 - s3;
                y5 = u6 - s5;
            end
            8'b00001010: begin
                y0 = u0 * s0;
                y1 = u2 * s1;
                y3 = u4 * s3;
                y5 = u6 * s5;
            end
            8'b00001011: begin
                y0 = u0 ^ s0;
                y1 = u2 ^ s1;
                y3 = u4 ^ s3;
                y5 = u6 ^ s5;
            end
            8'b00001100: begin
                y0 = u0 | s0;
                y1 = u2 | s1;
                y3 = u4 | s3;
                y5 = u6 | s5;
            end
            8'b00001101: begin
                y0 = u0 & s0;
                y1 = u2 & s1;
                y3 = u4 & s3;
                y5 = u6 & s5;
            end
            8'b00001110: begin
                y0 = u0 << 1;
                y1 = u2 << 1;
                y3 = u4 << 1;
                y5 = u6 << s5;
            end
            8'b00001111: begin
                y0 = u0 >> 1;
                y1 = u2 >> 1;
                y3 = u4 >> 1;
                y5 = u6 >> s5;
            end
            default: begin
                y0 = 16'b0;
                y1 = 16'b0;
                y2 = 16'b0;
                y3 = 16'b0;
                y4 = 16'b0;
                y5 = 16'b0;
                y6 = 16'b0;
                y7 = 16'b0;
            end
        endcase
    end

