module PC(PC_out,PC_in,load,inc,clk,rst);

output	[7:0]PC_out;
input	[7:0]PC_in;
input	load,inc,clk,rst;

reg [7:0] PC;
reg [1:0] state;
reg [1:0] prev_state;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        PC <= 8'b0;
        state <= 2'b00;
        prev_state <= 2'b00;
    end else begin
        if (load) begin
            PC <= PC_in;
            state <= 2'b01;
        end else if (inc) begin
            if (state == 2'b01) begin
                PC <= PC + 1;
                state <= 2'b10;
            end else if (state == 2'b10) begin
                PC <= PC + 1;
                state <= 2'b01;
            end
        end else begin
            state <= prev_state;
        end
        prev_state <= state;
    end
end

assign PC_out = PC;

endmodule

module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
) begin
    reg [DATA_WIDTH-1:0] reg_data;
    reg [DATA_WIDTH-1:0] reg_shifted_data;
    reg [1:0] reg_warning;

    always @(posedge clk or posedge ASYNC) begin
        if (ASYNC) begin
            reg_data <= din;
        end else begin
            reg_data <= reg_data << SHIFT_VALUE;
        end

        if (DATA_TYPE == "signed") begin
            if (reg_data > (2**(DATA_WIDTH-1) - 1)) begin
                reg_warning <= 2'b11;
            end else if (reg_data < -(2**(DATA_WIDTH-1))) begin
                reg_warning <= 2'b01;
            end else begin
                reg_warning <= 2'b00;
            end
        end else if (DATA_TYPE == "unsigned") begin
            if (reg_data > (2**DATA_WIDTH - 1)) begin
                reg_warning <= 2'b11;
            end else begin
                reg_warning <= 2'b00;
            end
        end

        reg_shifted_data <= reg_data;
        dout <= reg_shifted_data;
        warning <= reg_warning;
    end
endmodule

