module alu_32 (
  input wire [WORD_SIZE-1:0]	input_a,
  input wire [WORD_SIZE-1:0]	input_b,
  input wire [CONTROL_SIGNAL_SIZE-1:0]	control,
  output wire       zero,
  output reg	      cout,
  output reg	      err_overflow,
  output reg	      err_invalid_control,
  output reg [WORD_SIZE-1:0]	result
);

parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;

wire [WORD_SIZE-1:0] intermediate_result;
wire [WORD_SIZE-1:0] overflow_flag;
wire [WORD_SIZE-1:0] invalid_control_flag;

always @(posedge clk or negedge rst) begin
  if (rst) begin
    intermediate_result <= 0;
    overflow_flag <= 0;
    invalid_control_flag <= 0;
    zero <= 0;
    cout <= 0;
    err_overflow <= 0;
    err_invalid_control <= 0;
    result <= 0;
  end else begin
    case (control)
      AND: begin
        intermediate_result <= input_a & input_b;
        overflow_flag <= 0;
        invalid_control_flag <= 0;
        zero <= (intermediate_result == 0);
        cout <= 0;
        err_overflow <= 0;
        err_invalid_control <= 0;
        result <= intermediate_result;
      end
      OR: begin
        intermediate_result <= input_a | input_b;
        overflow_flag <= 0;
        invalid_control_flag <= 0;
        zero <= (intermediate_result == 0);
        cout <= 0;
        err_overflow <= 0;
        err_invalid_control <= 0;
        result <= intermediate_result;
      end
      ADD: begin
        intermediate_result <= input_a + input_b;
        overflow_flag <= (input_a[WORD_SIZE-1] == 1 && input_b[WORD_SIZE-1] == 1 && intermediate_result[WORD_SIZE-1] == 0) || (input_a[WORD_SIZE-1] == 0 && input_b[WORD_SIZE-1] == 0 && intermediate_result[WORD_SIZE-1] == 1);
        invalid_control_flag <= 0;
        zero <= (intermediate_result == 0);
        cout <= (intermediate_result[WORD_SIZE-1] == 1);
        err_overflow <= overflow_flag;
        err_invalid_control <= invalid_control_flag;
        result <= intermediate_result;
      end
      ADD_UNSIGNED: begin
        intermediate_result <= input_a + input_b;
        overflow_flag <= 0;
        invalid_control_flag <= 0;
        zero <= (intermediate_result == 0);
        cout <= (intermediate_result[WORD_SIZE-1] == 1);
        err_overflow <= overflow_flag;
        err_invalid_control <= invalid_control_flag;
        result <= intermediate_result;
      end
      SUB: begin
        intermediate_result <= input_a - input_b;
        overflow_flag <= (input_a[WORD_SIZE-1] == 1 && input_b[WORD_SIZE-1] == 0 && intermediate_result[WORD_SIZE-1] == 1) || (input_a[WORD_SIZE-1] == 0 && input_b[WORD_SIZE-1] == 1 && intermediate_result[WORD_SIZE-1] == 0);
        invalid_control_flag <= 0;
        zero <= (intermediate_result == 0);
        cout <= (intermediate_result[WORD_SIZE-1] == 1);
        err_overflow <= overflow_flag;
        err_invalid_control <= invalid_control_flag;
        result <= intermediate_result;
      end
      SLT: begin
        intermediate_result <= input_a < input_b;
        overflow_flag <= 0;
        invalid_control_flag <= 0;
        zero <= (intermediate_result == 0);
        cout <= (intermediate_result == 1);
        err_overflow <= overflow_flag;
        err_invalid_control <= invalid_control_flag;
        result <= intermediate_result;
      end
      NOR: begin
        intermediate_result <= ~input_a | ~input_b;
        overflow_flag <= 0;
        invalid_control_flag <= 0;
        zero <= (intermediate_result == 0);
        cout <= (intermediate_result == 1);
        err_overflow <= overflow_flag;
        err_invalid_control <= invalid_control_flag;
        result <= intermediate_result;
      end
      default: begin
        intermediate_result <= 0;
        overflow_flag <= 0;
        invalid_control_flag <= 1;
        zero <= 0;
        cout <= 0;
        err_overflow <= 0;
        err_invalid_control <= 1;
        result <= 0;
      end
    endcase
  end
end

endmodule

