module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);

    reg [BITS - 1:0] cnt;
    reg [BITS - 1:0] enable_wires [BITS - 1:0];

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt <= 0;
            enable_wires <= 0;
        end else begin
            if (ena) begin
                if (updown) begin
                    cnt <= cnt + 1;
                end else begin
                    cnt <= cnt - 1;
                end
            end
            if (cnt == 2**BITS - 1) begin
                ovf <= 1;
            end else if (cnt == 0) begin
                ovf <= 0;
            end
        end
    end

    assign out = cnt;
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);

reg [31:0] reg1;
reg [3:0] b1, s1, g1, q1;

always @(posedge clk or negedge rst) begin
	if (rst) begin
		reg1 <= 32'b0;
		b1 <= 4'b0;
		s1 <= 4'b0;
		g1 <= 4'b0;
		q1 <= 4'b0;
	end else begin
		reg1 <= reg1 + 1'b1;
		b1 <= reg1[15:12];
		s1 <= reg1[11:8];
		g1 <= reg1[7:4];
		q1 <= reg1[3:0];
		if (b1 > 4'b1111) begin
			b1 <= b1 + 4'b0003;
		end
		if (s1 > 4'b1111) begin
			s1 <= s1 + 4'b0003;
		end
		if (g1 > 4'b1111) begin
			g1 <= g1 + 4'b0003;
		end
		if (q1 > 4'b1111) begin
			q1 <= q1 + 4'b0003;
		end
		b <= b1;
		s <= s1;
		g <= g1;
		q <= q1;
	end
end

endmodule

module risc_v_32_mem(m_addr, d_f_mem, inst_decode, mem_out);
    input  [31:0] m_addr;                                    
    input  [31:0] d_f_mem;                                   
    input  [36:0] inst_decode;								 
	output reg [31:0] mem_out;

    // Extract instruction decode bits
    reg [2:0] i_lw, i_lbu, i_lb, i_lhu, i_lh;

    // Extract address bits
    reg [1:0] addr_align;

    // Decode instruction decode bits
    always @(posedge inst_decode) begin
        i_lw = inst_decode[2];
        i_lbu = inst_decode[3];
        i_lb = inst_decode[4];
        i_lhu = inst_decode[5];
        i_lh = inst_decode[6];
    end

    // Decode address bits
    always @(posedge m_addr) begin
        addr_align = m_addr[1];
    end

    // Combinational logic to produce the output
    always @(posedge inst_decode or posedge m_addr) begin
        case (i_lw)
            3'b000: mem_out = d_f_mem; // Load word
            3'b001: mem_out = d_f_mem[7:0]; // Load byte
            3'b010: mem_out = d_f_mem[15:0]; // Load half-word
            3'b011: mem_out = d_f_mem[31:0]; // Load word with sign extension
            3'b100: mem_out = d_f_mem[7:0]; // Load byte with sign extension
            3'b101: mem_out = d_f_mem[15:0]; // Load half-word with sign extension
            3'b110: mem_out = d_f_mem[31:0]; // Load word with sign extension
            default: mem_out = 32'h0; // Default to zero
        endcase

        // Align the data based on the address alignment
        if (addr_align == 1'b0) begin
