module peridot_ethio_cdb_signal (
	input wire			reset,
	input wire			clk,
	input wire			in_sig,
	output wire			out_sig,
	output wire			riseedge,
	output wire			falledge
);

reg [2:0] shift_reg;
reg [1:0] edge_state;

always @(posedge clk or posedge reset) begin
	if (reset) begin
		shift_reg <= 3'b000;
		edge_state <= 2'b00;
	end else begin
		shift_reg <= {shift_reg[1:0], in_sig};
		edge_state <= {edge_state[1:0], in_sig};
		if (edge_state == 2'b11) begin
			riseedge <= 1'b1;
			falledge <= 1'b0;
		end else if (edge_state == 2'b00) begin
			riseedge <= 1'b0;
			falledge <= 1'b0;
		end else if (edge_state == 2'b10) begin
			riseedge <= 1'b0;
			falledge <= 1'b1;
		end else if (edge_state == 2'b01) begin
			riseedge <= 1'b1;
			falledge <= 1'b0;
		end
	end
end

assign out_sig = in_sig;
assign riseedge = edge_state[1];
assign falledge = edge_state[0];

endmodule

module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
);

reg [15:0] rd_compl_tag_reg;
reg [15:0] bm_tag_reg;
reg rd_compl_start_reg;
reg rd_compl_done_reg;
reg bm_done_reg;
reg [15:0] op_tag_reg;
reg op_done_reg;

always @(posedge CLK or posedge RESET) begin
    if (RESET) begin
        rd_compl_tag_reg <= 16'b0;
        bm_tag_reg <= 16'b0;
        rd_compl_start_reg <= 1'b0;
        rd_compl_done_reg <= 1'b0;
        bm_done_reg <= 1'b0;
        op_tag_reg <= 16'b0;
        op_done_reg <= 1'b0;
    end else begin
        rd_compl_tag_reg <= RD_COMPL_TAG;
        bm_tag_reg <= BM_TAG;
        rd_compl_start_reg <= RD_COMPL_START;
        rd_compl_done_reg <= RD_COMPL_DONE;
        bm_done_reg <= BM_DONE;
        if (rd_compl_start_reg && !rd_compl_done_reg) begin
            op_tag_reg <= rd_compl_tag_reg;
            op_done_reg <= 1'b1;
        end else if (bm_done_reg) begin
            op_tag_reg <= bm_tag_reg;
            op_done_reg <= 1'b1;
        end else begin
            op_tag_reg <= 16'b0;
            op_done_reg <= 1'b0;
        end
    end
end

assign OP_TAG = op_tag_reg;
assign OP_DONE = op_done_reg;

endmodule

