    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );

input  clk;
input  shiftnld;
input  captnupdt;

reg [1:0] temp_reg;
reg [1:0] temp_reg2;
reg [1:0] temp_reg3;
reg [1:0] temp_reg4;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        temp_reg <= 2'b00;
        temp_reg2 <= 2'b00;
        temp_reg3 <= 2'b00;
        temp_reg4 <= 2'b00;
    end else begin
        case (captnupdt & shiftnld)
            2'b10: begin
                temp_reg <= 2'b01;
                temp_reg2 <= 2'b00;
                temp_reg3 <= 2'b00;
                temp_reg4 <= 2'b00;
            end
            2'b11: begin
                temp_reg <= 2'b01;
                temp_reg2 <= 2'b01;
                temp_reg3 <= 2'b00;
                temp_reg4 <= 2'b00;
            end
            2'b01: begin
                temp_reg <= 2'b00;
                temp_reg2 <= 2'b01;
                temp_reg3 <= 2'b00;
                temp_reg4 <= 2'b00;
            end
            2'b00: begin
                temp_reg <= 2'b00;
                temp_reg2 <= 2'b00;
                temp_reg3 <= 2'b00;
                temp_reg4 <= 2'b00;
