module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);

    // Counter for horizontal position
    reg [15:0] H_cnt;
    // Counter for vertical position
    reg [15:0] V_cnt;

    // Intermediate signals for sync generation
    reg Pout_de_w;
    reg Pout_hs_w;
    reg Pout_vs_w;
    reg Rden_w;

    // Polarity inversion for sync signals
    reg hs_pol_inv;
    reg vs_pol_inv;

    // Reset signal
    reg rst;

    // Clock signal
    reg clk;

    // Initialize counters and reset signal
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            H_cnt <= 16'b0;
            V_cnt <= 16'b0;
            Pout_de_w <= 1'b0;
            Pout_hs_w <= 1'b0;
            Pout_vs_w <= 1'b0;
            Rden_w <= 1'b0;
            hs_pol_inv <= 1'b0;
            vs_pol_inv <= 1'b0;
        end else begin
            H_cnt <= H_cnt + 1'b1;
            V_cnt <= V_cnt + 1'b1;
            Pout_de_w <= (H_cnt == I_h_total) ? 1'b1 : 1'b0;
            Pout_hs_w <= (H_cnt == I_h_sync) ? 1'b1 : 1'b0;
            Pout_vs_w <= (V_cnt == I_v_sync) ? 1'b1 : 1'b0;
            Rden_w <= (H_cnt == I_rd_hres) ? 1'b1 : 1'b0;
            hs_pol_inv <= I_hs_pol;
            vs_pol_inv <= I_vs_pol;
        end
    end

    // Delayed intermediate signals
    always @(posedge clk) begin
        O_de <= Pout_de_w;
        O_hs <= Pout_hs_w;
        O_vs <= Pout_vs_w;
        O_rden <= Rden_w;
    end

endmodule

module alt_sld_fab_alt_sld_fab_ident
(
	input [4:0] address_0,
	input [3:0] contrib_0,
	output [3:0] rdata_0,
	output [3:0] mixed
)
(
	// Constant data array
	reg [127:0] constant_data_array;

	// Address decoding logic
	reg [2:0] address_decode;

	// Data selection logic
	reg [3:0] rdata_0;
	reg [3:0] mixed;

	// Always block for data selection and mixing
	always @(posedge clk or negedge rst)
	begin
		// Decode the address
		case (address_0)
			0: address_decode = 3'b000;
			1: address_decode = 3'b001;
			2: address_decode = 3'b010;
			3: address_decode = 3'b011;
			4: address_decode = 3'b100;
			5: address_decode = 3'b101;
			6: address_decode = 3'b110;
			7: address_decode = 3'b111;
			default: address_decode = 3'b000; // Default to 0 if address is out of range
		endcase

		// Select the appropriate data slice from the constant data array
		case (address_decode)
			0: rdata_0 = constant_data_array[0:3];
			1: rdata_0 = constant_data_array[4:7];
			2: rdata_0 = constant_data_array[8:11];
			3: rdata_0 = constant_data_array[12:15];
			4: rdata_0 = constant_data_array[16:19];
			5: rdata_0 = constant_data_array[20:23];
			6: rdata_0 = constant_data_array[24:27];
			7: rdata_0 = constant_data_array[28:31];
			default: rdata_0 = 4'b0000; // Default to 0 if address is out of range
		endcase

		// Mix the contribution input without modification
		mixed = contrib_0;
	end
endmodule

