module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);

    reg [1:0] counter; // Counter to track output transitions
    reg [1:0] prev_Q; // Previous value of Q for power dissipation calculation

    always @(posedge CLK or posedge CLR_BAR) begin
        if (CLR_BAR) begin
            Q <= 0;
            counter <= 0;
            prev_Q <= 0;
        end else begin
            if (D == 1) begin
                Q <= 1;
                counter <= counter + 1;
                prev_Q <= Q;
            end else begin
                Q <= 0;
                counter <= counter + 1;
                prev_Q <= Q;
            end
        end
    end

    always @(posedge CLK) begin
        if (Q != prev_Q) begin
            $display("Power Dissipation: %d", counter * C_L * Vcc^2);
            counter <= 0;
        end
    end

endmodule

