    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
)
    (
        .clk(clk),
        .aclr(aclr),
        .empty_n(empty_n),
        .full_n(full_n),
        .read(read),
        .write(write),
        .dout(dout),
        .din(din)
    );
    // Internal registers
    reg [DATA_BITS-1:0] mem[0:DEPTH-1];
    reg [DATA_BITS-1:0] index;
    reg empty;
    reg full;
    // Control logic
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            empty <= 1'b1;
            full <= 1'b0;
            index <= 0;
            for (int i = 0; i < DEPTH; i++) begin
                mem[i] <= 0;
            end
        end else begin
            if (write && !full) begin
                mem[index] <= din;
                index <= (index + 1) % DEPTH;
                full <= 1'b1;
            end else if (read && !empty) begin
                dout <= mem[index];
                index <= (index + 1) % DEPTH;
                empty <= 1'b0;
            end
        end
    end
endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg [31:0] pre;
reg [31:0] current_input;
reg [31:0] previous_input;
reg [31:0] debounced_output;

always @(posedge clk) begin
    if (timer == 1000000) begin
        if (current_input == previous_input) begin
            debounced_output <= current_input;
        end
        timer <= 0;
        previous_input <= current_input;
    end else begin
        timer <= timer + 1;
    end
end

assign current_input = btn_input;
assign btn_output = debounced_output;
endmodule

