module edge_detector (
    input wire clk,          
    input wire rst_n,        
    input wire signal_in,    
    output reg rising_out,   
    output reg falling_out   
);

    reg [1:0] signal_in_prev; // Internal register to store the previous state of signal_in

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Initialize outputs and internal register to zero
            rising_out <= 0;
            falling_out <= 0;
            signal_in_prev <= 0;
        end else begin
            // Update the internal register with the current state of signal_in
            signal_in_prev <= signal_in;

            // Detect rising edge
            if (signal_in_prev == 0 && signal_in == 1) begin
                rising_out <= 1;
            end else begin
                rising_out <= 0;
            end

            // Detect falling edge
            if (signal_in_prev == 1 && signal_in == 0) begin
                falling_out <= 1;
            end else begin
                falling_out <= 0;
            end
        end
    end

endmodule

module altr_hps_gray2bin (
