module ISOLORX1 (
    input   ISO,
    input   D,
    output  Q
);

// Conditional delays based on functional macro definition
`ifdef FUNCTIONAL_MACRO
    localparam DELAY_D_LOW_TO_HIGH = 47;
    localparam DELAY_D_HIGH_TO_LOW = 50;
    localparam DELAY_ISO_LOW_TO_HIGH = 59;
    localparam DELAY_ISO_HIGH_TO_LOW = 58;
`else
    localparam DELAY_D_LOW_TO_HIGH = 0; // No delay for D
    localparam DELAY_D_HIGH_TO_LOW = 0; // No delay for D
    localparam DELAY_ISO_LOW_TO_HIGH = 0; // No delay for ISO
    localparam DELAY_ISO_HIGH_TO_LOW = 0; // No delay for ISO
`endif

// Combinational OR gate with conditional delays
assign Q = ISO | D;

// Propagation delays for input D
always @(posedge D or negedge D) begin
    if (D) begin
        Q <= Q | #DELAY_D_HIGH_TO_LOW Q;
    end else begin
        Q <= Q | #DELAY_D_LOW_TO_HIGH Q;
    end
end

// Propagation delays for input ISO
always @(posedge ISO or negedge ISO) begin
    if (ISO) begin
        Q <= Q | #DELAY_ISO_HIGH_TO_LOW Q;
    end else begin
        Q <= Q | #DELAY_ISO_LOW_TO_HIGH Q;
    end
end

endmodule

module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
  reg [23:0]              r_rgb;
  reg [23:0]              r_count;
  reg [1:0]                 state;
  reg                       fifo_ready;
  reg                       fifo_active;
  reg                       fifo_stb;
  reg                       fifo_data;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      r_rgb <= 24'b0;
      r_count <= 0;
      state <= IDLE;
      fifo_ready <= 0;
      fifo_active <= 0;
      fifo_stb <= 0;
      fifo_data <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (i_data_en && i_h_sync && i_v_sync) begin
            r_rgb <= i_rgb;
            r_count <= 0;
            state <= READY;
          end
        end
        READY: begin
          if (i_h_sync && i_v_sync) begin
            r_count <= r_count + 1;
            if (r_count == i_ppfifo_size) begin
              state <= RELEASE;
            end
          end
        end
        RELEASE: begin
          if (i_h_sync && i_v_sync) begin
            state <= IDLE;
            fifo_ready <= 0;
            fifo_active <= 0;
            fifo_stb <= 0;
            fifo_data <= 0;
          end
        end
      endcase

      if (fifo_ready && i_h_sync && i_v_sync) begin
        fifo_active <= 1;
        fifo_stb <= 1;
        fifo_data <= r_rgb;
      end else begin
        fifo_active <= 0;
        fifo_stb <= 0;
