module oh_lat1
  #(parameter N    = 1,        
    parameter SYN  = "TRUE",   
    parameter TYPE = "DEFAULT" 
    )
   (input 	   clk, 
    input [N-1:0]  in,  
    output [N-1:0] out  
    );

  reg [N-1:0] out_reg;
  reg [N-1:0] in_reg;

  always @(posedge clk) begin
    if (SYN == "TRUE") begin
      out_reg <= in;
      out <= out_reg;
    end else begin
      for (int i = 0; i < N; i = i + 1) begin
        asic_lat1 #(.TYPE(TYPE)) latch (
          .clk(clk),
          .in(in[i]),
          .out(out_reg[i])
        );
      end
    end
  end

