module TopModule (
    input clk,
    input x,
    output z
);

    // Define the states of the FSM
    enum { IDLE, XOR, AND, OR } state;

    // Define the flip-flops
    reg [1:0] flipFlops[2];

    // Define the NOR gate
    reg [1:0] norGate;

    // Define the output of the NOR gate
    assign z = norGate;

    // Define the state transitions
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                flipFlops[0] <= 2'b00;
                flipFlops[1] <= 2'b00;
                state <= XOR;
            end
            XOR: begin
                flipFlops[0] <= ~flipFlops[0];
                flipFlops[1] <= ~flipFlops[1];
                state <= AND;
            end
            AND: begin
                flipFlops[0] <= flipFlops[0] & flipFlops[1];
                flipFlops[1] <= flipFlops[0] & flipFlops[1];
                state <= OR;
            end
            OR: begin
                flipFlops[0] <= flipFlops[0] | flipFlops[1];
                flipFlops[1] <= flipFlops[0] | flipFlops[1];
                state <= IDLE;
            end
        endcase
    end

    // Define the NOR gate logic
    always @(posedge clk) begin
        norGate <= flipFlops[0] ^ flipFlops[1];
    end

endmodule

module TopModule (
    input clk,
    input areset,
    input train_valid,
    input train_taken,
    output reg [1:0] state
);

    reg [1:0] counter;
    reg train_valid_prev;
    reg train_taken_prev;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            counter <= 2'b01;
            train_valid_prev <= 1'b0;
            train_taken_prev <= 1'b0;
        end else begin
            train_valid_prev <= train_valid;
            train_taken_prev <= train_taken;

            if (train_valid_prev && train_taken_prev) begin
                if (counter < 3'b11) begin
                    counter <= counter + 1'b1;
                end else begin
                    counter <= 2'b01;
                end
            end else if (train_valid_prev && ~train_taken_prev) begin
                if (counter > 2'b00) begin
                    counter <= counter - 1'b1;
                end else begin
                    counter <= 2'b10;
                end
            end
        end
    end

    assign state = counter;

endmodule

