module TopModule (
    input clk,
    input reset,
    output reg [31:0] q
);

    // Define the LFSR state
    reg [31:0] lfsr_state = 32'h1;

    // Define the taps
    localparam TAP_32 = 32;
    localparam TAP_22 = 22;
    localparam TAP_2 = 2;
    localparam TAP_1 = 1;

    // Define the XOR gates
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            lfsr_state <= 32'h1;
            q <= 32'h1;
        end else begin
            // Shift the LFSR state
            lfsr_state = {lfsr_state[30:0], lfsr_state[31]};

            // XOR the taps
            reg [31:0] xor_result = 32'h0;
            xor_result = xor_result ^ (lfsr_state[TAP_32] ? lfsr_state[0] : 0);
            xor_result = xor_result ^ (lfsr_state[TAP_22] ? lfsr_state[1] : 0);
            xor_result = xor_result ^ (lfsr_state[TAP_2] ? lfsr_state[2] : 0);
            xor_result = xor_result ^ (lfsr_state[TAP_1] ? lfsr_state[31] : 0);

            // Update the LFSR state
            lfsr_state = {lfsr_state[30:0], xor_result};
        end
    end

    // Assign the output
    assign q = lfsr_state;

endmodule

