module TopModule (
    input clk,
    input reset,
    output reg [4:0] q
);

    // Define the LFSR parameters
    localparam N = 5; // Number of bits in the LFSR
    localparam TAPS = 2; // Number of taps
    localparam TAP1 = 5; // First tap position
    localparam TAP2 = 3; // Second tap position

    // Initialize the LFSR state
    reg [N-1:0] lfsr_state = 1'b1;

    // Define the LFSR logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            lfsr_state <= 1'b1;
        end else begin
            // Shift the LFSR
            reg [N-1:0] shifted_state = {lfsr_state[TAPS-1], lfsr_state[TAPS:N-1]};

            // XOR the taps
            reg [N-1:0] xor_result = shifted_state[TAP1] ^ shifted_state[TAP2];

            // Update the LFSR state
            lfsr_state <= shifted_state ^ xor_result;
        end
    end

    // Assign the LFSR output to the q port
    assign q = lfsr_state;

endmodule

