        assign left_neighbour = (i == 0) ? in[99] : in[i-1];

        // Calculate the right neighbour
        assign right_neighbour = (i == 99) ? in[0] : in[i+1];

        // Update the output vectors
        if (in[i] == 1 && left_neighbour == 1) begin
