module TopModule (
    input clk,
    input load,
    input [511:0] data,
    output [511:0] q
);

    // Define the state of each cell
    reg [1:0] cell_state [0:511];

    // Initialize the state of the cells
    initial begin
        for (int i = 0; i <= 511; i = i + 1) begin
            cell_state[i] = 2'b00; // Off
        end
    end

    // Rule 110 logic
    always @(posedge clk) begin
        if (load) begin
            for (int i = 0; i <= 511; i = i + 1) begin
                cell_state[i] = data[i];
            end
        end else begin
            for (int i = 1; i <= 510; i = i + 1) begin
                cell_state[i] = cell_state[i-1] ^ cell_state[i] ^ cell_state[i+1];
            end
            cell_state[0] = cell_state[511];
            cell_state[511] = cell_state[0];
        end
    end

    // Output the state of the cells
    assign q = cell_state;

endmodule

