module TopModule (
    input clk,
    input resetn,
    input [2:0] r,
    output [2:0] g
);

    // State codes
    localparam A = 3'b000;
    localparam B = 3'b001;
    localparam C = 3'b010;
    localparam D = 3'b011;

    // State variables
    reg [2:0] state;
    reg [2:0] next_state;

    // State flip-flops
    always @(posedge clk or posedge resetn) begin
        if (resetn) begin
            state <= A;
        end else begin
            state <= next_state;
        end
    end

    // State table
    always @(posedge clk or posedge resetn) begin
        if (resetn) begin
            next_state <= A;
        end else begin
            case (state)
                A: begin
                    if (r[0] == 1) begin
                        next_state <= B;
                    end else if (r[1] == 1) begin
                        next_state <= C;
                    end else if (r[2] == 1) begin
                        next_state <= D;
                    end else begin
                        next_state <= A;
                    end
                end
                B: begin
                    if (r[0] == 1) begin
                        next_state <= B;
                    end else if (r[1] == 1) begin
                        next_state <= A;
                    end else if (r[2] == 1) begin
                        next_state <= D;
                    end else begin
                        next_state <= A;
                    end
                end
                C: begin
                    if (r[0] == 1) begin
                        next_state <= C;
                    end else if (r[1] == 1) begin
                        next_state <= A;
                    end else if (r[2] == 1) begin
                        next_state <= D;
                    end else begin
                        next_state <= A;
                    end
                end
                D: begin
                    if (r[0] == 1) begin
                        next_state <= B;
                    end else if (r[1] == 1) begin
                        next_state <= A;
                    end else if (r[2] == 1) begin
                        next_state <= D;
                    end else begin
                        next_state <= A;
                    end
                end
            endcase
        end
    end

    // Output assignment
    assign g = state;

endmodule

