            reset <= 1'b1;
            clk_in <= 1'b0;
        end else begin
            gshare_index <= gshare_index + 1'b1;
            gshare_history <= gshare_history + 1'b1;
            gshare_table <= gshare_table + 1'b1;
            gshare_table_entry <= gshare_table_entry + 1'b1;
            branch_history <= branch_history + 1'b1;
            pht <= pht + 1'b1;
            pht_entry <= pht_entry + 1'b1;
            predict_state <= predict_state + 1'b1;
            train_state <= train_state + 1'b1;
            predict_taken_out <= predict_taken_out + 1'b1;
            predict_history_out <= predict_history_out + 1'b1;
            predict_valid_in <= predict_valid;
            predict_pc_in <= predict_pc;
            train_valid_in <= train_valid;
            train_taken_in <= train_taken;
            train_mispredicted_in <= train_mispredicted;
            train_history_in <= train_history;
            train_pc_in <= train_pc;
            reset <= reset;
            clk_in <= clk;
        end
    end

    // Define the branch predictor logic
    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            predict_state <= 2'b0;
            train_state <= 2'b0;
        end else begin
            if (predict_valid_in) begin
                gshare_index <= predict_pc_in[6:0];
                gshare_history <= predict_pc_in[6:0];
                gshare_table_entry[gshare_index] <= gshare_table_entry[gshare_index] + 1'b1;
                if (gshare_table_entry[gshare_index] == 2'b11) begin
                    gshare_table_entry[gshare_index] <= 2'b00;
                end
                predict_state <= 2'b0;
            end else if (train_valid_in) begin
                if (train_mispredicted_in) begin
                    gshare_table_entry[gshare_index] <= 2'b00;
                end
                pht_entry[gshare_index] <= train_history_in;
                predict_state <= 2'b0;
            end else begin
                if (predict_state == 2'b0) begin
                    gshare_index <= gshare_index + 1'b1;
                    gshare_history <= gshare_history + 1'b1;
                    gshare_table_entry[gshare_index] <= gshare_table_entry[gshare_index] + 1'b1;
                    if (gshare_table_entry[gshare_index] == 2'b11) begin
                        gshare_table_entry[gshare_index] <= 2'b00;
                    end
                    predict_state <= 2'b0;
                end else if (predict_state == 2'b1) begin
                    predict_taken_out <= gshare_table_entry[gshare_index];
                    predict_history_out <= gshare_history;
                    predict_state <= 2'b0;
                end else if (predict_state == 2'b2) begin
                    predict_taken_out <= pht_entry[gshare_index];
                    predict_history_out <= gshare_history;
                    predict_state <= 2'b0;
                end
            end
        end
    end

    // Define the branch predictor output
    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            predict_taken_out <= 1'b0;
            predict_history_out <= 7'b0;
        end else begin
            predict_taken_out <= predict_taken_out;
            predict_history_out <= predict_history_out;
        end
    end

endmodule

module TopModule (
    input clk,
    input reset,
    input [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    reg [23:0] message;
    reg [2:0] state;
    reg [2:0] byte_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            message <= 0;
            state <= 0;
            byte_count <= 0;
            done <= 0;
        end else begin
            case (state)
                0: begin
                    if (in[3] == 1) begin
                        state <= 1;
                        byte_count <= 0;
                    end
                end
                1: begin
                    if (byte_count < 3) begin
                        message[23 - byte_count] = in;
                        byte_count <= byte_count + 1;
                    end else begin
                        state <= 2;
                        done <= 1;
                    end
                end
                2: begin
                    if (in[3] == 1) begin
                        state <= 1;
                        byte_count <= 0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out_bytes <= 0;
        end else begin
            if (done) begin
                out_bytes <= message;
            end
        end
    end

endmodule

module TopModule (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    input dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // Define the states of the FSM
    typedef enum {IDLE, FALLING, DIGGING, SPLATTERING} FSM_STATE;

    // Initialize the FSM state
    FSM_STATE current_state = IDLE;

    // Define the state transitions
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= IDLE;
            walk_left <= 0;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            case (current_state)
                IDLE: begin
                    if (bump_left) begin
                        current_state <= FALLING;
                        walk_left <= 0;
                        walk_right <= 1;
                    end else if (bump_right) begin
                        current_state <= FALLING;
                        walk_left <= 1;
                        walk_right <= 0;
                    end else if (ground) begin
                        current_state <= DIGGING;
                        walk_left <= 0;
                        walk_right <= 0;
                    end else begin
                        current_state <= IDLE;
                    end
                end
                FALLING: begin
                    if (ground) begin
                        current_state <= DIGGING;
                        walk_left <= 0;
                        walk_right <= 0;
                    end else begin
                        current_state <= FALLING;
                    end
                end
                DIGGING: begin
                    if (ground) begin
                        current_state <= IDLE;
                        walk_left <= 0;
                        walk_right <= 0;
                    end else begin
                        current_state <= DIGGING;
                    end
                end
                SPLATTERING: begin
                    current_state <= SPLATTERING;
                end
            endcase
        end
    end

    // Assign the outputs based on the current state
    assign walk_left = current_state == IDLE || current_state == FALLING || current_state == DIGGING;
    assign walk_right = current_state == IDLE || current_state == FALLING || current_state == DIGGING;
    assign aaah = current_state == IDLE || current_state == FALLING || current_state == DIGGING;
    assign digging = current_state == IDLE || current_state == FALLING || current_state == DIGGING;

endmodule

